import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getOrderStatus, answerOrderQuestion } from '../src/order-agent.js';
import { scriptedModel } from './helpers/mock-model.js';

test('getOrderStatus tool returns order if it belongs to customer', async () => {
  const result = await getOrderStatus.execute({ orderId: 'A100' }, { context: { customerId: 'C1' } });
  assert.deepEqual(result, { orderId: 'A100', status: 'shipped', eta: '2026-10-09' });
});

test('getOrderStatus tool returns error if order does not belong to customer', async () => {
  const result = await getOrderStatus.execute({ orderId: 'B200' }, { context: { customerId: 'C1' } });
  assert.deepEqual(result, { orderId: 'B200', error: 'not found' });
});

test('getOrderStatus tool returns error if order does not exist', async () => {
  const result = await getOrderStatus.execute({ orderId: 'Z999' }, { context: { customerId: 'C1' } });
  assert.deepEqual(result, { orderId: 'Z999', error: 'not found' });
});

test('answerOrderQuestion answers a customer question', async () => {
  const model = scriptedModel([
    { toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A100' } }], usage: [100, 7] },
    { text: 'Your order A100 has been shipped and will arrive on 2026-10-09.', usage: [200, 9] },
  ]);

  const result = await answerOrderQuestion(model, 'What is the status of my order?', { customerId: 'C1' });

  assert.equal(result.answer, 'Your order A100 has been shipped and will arrive on 2026-10-09.');
  assert.deepEqual(result.lookedUp, ['A100']);
  assert.equal(result.inputTokens, 300);
  assert.equal(result.outputTokens, 16);
});

test('answerOrderQuestion can look up multiple orders', async () => {
  const model = scriptedModel([
    { toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A100' } }], usage: [100, 7] },
    { toolCalls: [{ name: 'getOrderStatus', input: { orderId: 'A101' } }], usage: [110, 8] },
    { text: 'Your first order A100 shipped on 2026-10-09. Your second order A101 is still processing and will ship by 2026-10-14.', usage: [300, 20] },
  ]);

  const result = await answerOrderQuestion(model, 'Tell me about both my orders', { customerId: 'C1' });

  assert.equal(result.answer, 'Your first order A100 shipped on 2026-10-09. Your second order A101 is still processing and will ship by 2026-10-14.');
  assert.deepEqual(result.lookedUp, ['A100', 'A101']);
  assert.equal(result.inputTokens, 510);
  assert.equal(result.outputTokens, 35);
});

